import{_ as e,o,c as d,a2 as r}from"./chunks/framework.DYPTBNgj.js";const p=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keyboard-shortcuts.md","filePath":"guide/keyboard-shortcuts.md"}'),a={name:"guide/keyboard-shortcuts.md"};function n(i,t,c,s,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Every shortcut below appears in the app itself: click <strong>Shortcuts</strong> in the toolbar (next to Credentials and Settings), or press <strong>?</strong> anywhere on the canvas, to open the same list. Two rows are exceptions to that. One notes a second working key combo the in-app list leaves out — <code>Backspace</code> for Delete, already documented in <a href="./../getting-started/getting-started">Getting Started</a>. The other, <code>Ctrl+Shift+C</code> for Chat, is missing from the in-app list altogether, not just a second combo for an action already there — confirmed directly against <code>toolbar.ts</code>. Everything else here matches the in-app list exactly.</p><h2 id="canvas" tabindex="-1">Canvas <a class="header-anchor" href="#canvas" aria-label="Permalink to &quot;Canvas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Search / command palette — with the pointer over the canvas, the node you pick lands under it</td><td><code>Space</code> or <code>Ctrl+K</code></td></tr><tr><td>Pan canvas</td><td>Middle-drag, trackpad scroll, or <code>Shift</code>+scroll</td></tr><tr><td>Zoom</td><td>Scroll with a mouse wheel, <code>Ctrl</code>+scroll, or pinch</td></tr><tr><td>Fit to screen</td><td><code>Ctrl+Shift+F</code></td></tr><tr><td>Toggle minimap (not while editing a field)</td><td><code>M</code></td></tr><tr><td>Add a sticky note (not while editing a field)</td><td><code>N</code></td></tr><tr><td>Frame the selected nodes in a group</td><td><code>Ctrl+G</code></td></tr><tr><td>Show or hide notes (not while editing a field)</td><td><code>Shift+N</code></td></tr><tr><td>Move a group frame without the nodes inside it</td><td>Alt-drag its title</td></tr><tr><td>Follow a link in a note</td><td><code>Ctrl</code>/<code>Cmd</code>+click</td></tr><tr><td>Context menu — add a node, note or frame, or act on a node, note, frame or wire; the menu key opens it for the selection, or at the pointer when nothing is selected</td><td>Right-click, <code>Menu</code> or <code>Shift+F10</code></td></tr><tr><td>Focus mode — hides the sidebar for a distraction-free canvas</td><td><code>F</code> (not while editing a field)</td></tr><tr><td>Close panel, from an empty area of the canvas</td><td>Double-click</td></tr></tbody></table><h2 id="selection-editing" tabindex="-1">Selection &amp; Editing <a class="header-anchor" href="#selection-editing" aria-label="Permalink to &quot;Selection &amp; Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Box select — selects every node the box touches, not only those it fully covers</td><td>Shift-drag</td></tr><tr><td>Select all</td><td><code>Ctrl+A</code></td></tr><tr><td>Duplicate</td><td><code>Ctrl+D</code></td></tr><tr><td>Copy, cut or paste the selected nodes, notes and frames. Wires between the selected items come along; wires to items you did not select, and saved-connection bindings, do not. Paste lands under the pointer when it is over the canvas, otherwise slightly offset from the original. The clipboard stays inside Aerini and is shared between open workflows. One <code>Ctrl+Z</code> undoes a paste or a cut. Right-click empty canvas and choose <strong>Paste</strong> to place it there</td><td><code>Ctrl+C</code>, <code>Ctrl+X</code>, <code>Ctrl+V</code></td></tr><tr><td>Delete</td><td><code>Del</code> or <code>Backspace</code></td></tr><tr><td>Undo — the toolbar&#39;s <strong>Undo</strong> button does the same, and its tooltip names the step. Covers adding, deleting, moving, and wiring nodes, plus renaming, disabling, choosing a saved credential, and changing a node&#39;s settings. History is per open workflow and is cleared when you switch to another</td><td><code>Ctrl+Z</code></td></tr><tr><td>Redo — also a toolbar button</td><td><code>Ctrl+Y</code> or <code>Ctrl+Shift+Z</code></td></tr><tr><td>Cut connector</td><td>Alt-drag across it</td></tr><tr><td>Move where a wire ends — drag from the wired input, or click the wire and drag the ring on its input end; dropping anywhere else cancels, and <code>Esc</code> cancels mid-drag. On an input that takes many wires, such as Merge&#39;s, click the wire first</td><td>Drag</td></tr><tr><td>Wire backwards — drag from an empty input to an output, or release over empty canvas to pick a node to connect into it</td><td>Drag</td></tr><tr><td>Move every wire leaving an output to another output — drag from the output, then drop on a different output; one <code>Ctrl+Z</code> undoes it</td><td><code>Ctrl</code>/<code>Cmd</code>-drag</td></tr><tr><td>Disconnect a wire — hover it and click <strong>×</strong>, click it and press <code>Del</code>, or right-click it and choose <strong>Delete connection</strong></td><td><code>Del</code></td></tr></tbody></table><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Save</td><td><code>Ctrl+S</code></td></tr><tr><td>New workflow</td><td><code>Ctrl+N</code></td></tr><tr><td>Run workflow</td><td><code>Ctrl+Enter</code></td></tr><tr><td>Open <a href="./chat-panel">Chat</a> — needs a Webhook and an Output node</td><td><code>Ctrl+Shift+C</code></td></tr><tr><td>Show this shortcut list</td><td><code>?</code></td></tr><tr><td>Navigate the workflow list</td><td><code>↑</code> <code>↓</code></td></tr><tr><td>Open the selected item in the list</td><td><code>Enter</code></td></tr><tr><td>Rename an item in the list</td><td>Double-click</td></tr><tr><td>Open a workflow row&#39;s menu</td><td>Right-click</td></tr></tbody></table><h2 id="node-config" tabindex="-1">Node Config <a class="header-anchor" href="#node-config" aria-label="Permalink to &quot;Node Config&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Open a node&#39;s config panel</td><td>Double-click the node</td></tr><tr><td>Close the config panel</td><td><code>Esc</code></td></tr><tr><td>Insert node data into any field</td><td><code>{{</code></td></tr></tbody></table><p>On macOS, <code>Ctrl</code> in the table above is <code>Cmd</code>; both work everywhere Aerini checks for one.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../getting-started/getting-started">Getting Started</a> uses several of these (<code>Ctrl+S</code>, <code>Delete</code>) as they come up naturally while you build your first workflow.</li><li><a href="./expressions">Expressions</a> covers what <code>{{</code> inserts and how to build on it.</li><li><a href="./nodes">Nodes Reference</a> for what actually lives inside a node&#39;s config panel once you open it.</li><li><a href="./chat-panel">Chat Panel</a> for what <code>Ctrl+Shift+C</code> opens and why it&#39;s conditional on the workflow&#39;s nodes.</li></ul>',13)])])}const g=e(a,[["render",n]]);export{p as __pageData,g as default};
